import {api,AccountStore} from './accounts.mjs';
import {markup,setText} from './language.mjs';
import {updateFieldRequirements} from './forms.mjs';
function failure(root,error){const out=root.querySelector('[data-recovery-error]');if(out&&root.isConnected){setText(out,error.message);out.hidden=false;}}
async function run(root,form,action){const fields=[...root.querySelectorAll('input,button,select')],states=fields.map(e=>e.disabled);root.querySelector('[data-recovery-error]').hidden=true;fields.forEach(e=>e.disabled=true);try{if(!navigator.onLine)throw new Error('Connect to the internet to recover your account.');await action();}catch(error){if(form.isConnected)failure(root,error);}finally{fields.forEach((e,i)=>e.disabled=states[i]);}}
export function mountForgotPassword(root,{username='',onBack,onComplete}){
 root.innerHTML=markup('<h2>Forgot your password?</h2><p>Your clinic can help you get back into your account. Staff check your identity and give you a one-time recovery code.</p><div class="auth-tabs" role="group" aria-label="Password recovery"><button type="button" class="button primary" id="choose-recovery-request" aria-pressed="true">Request clinic help</button><button type="button" class="button secondary" id="choose-recovery-code" aria-pressed="false">I have a recovery code</button></div><form id="recovery-request-form"><label for="recovery-request-username">Username</label><input id="recovery-request-username" name="username" autocomplete="username" autocapitalize="none" spellcheck="false" minlength="3" maxlength="40" required><p class="hint">After requesting help, contact your clinic to verify your identity. A code is not sent automatically.</p><button class="button primary" type="submit">Request clinic help</button></form><form id="recovery-reset-form" hidden><label for="recovery-username">Username</label><input id="recovery-username" name="username" autocomplete="username" autocapitalize="none" spellcheck="false" minlength="3" maxlength="40" required><label for="recovery-code">Recovery code from the clinic</label><input id="recovery-code" name="code" autocomplete="one-time-code" autocapitalize="characters" spellcheck="false" maxlength="64" required><p class="hint">Codes expire after 15 minutes and can be used once.</p><label for="recovery-password">New password</label><input id="recovery-password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><label for="recovery-confirm">Confirm new password</label><input id="recovery-confirm" name="confirmPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><p class="hint">Use 12–128 characters. Staff do not need to know your new password.</p><button class="button primary" type="submit">Reset password</button></form><p class="notice warning" data-recovery-error role="alert" hidden></p><p id="recovery-request-success" class="notice good" role="status" hidden></p><p class="data-note">Staff accounts need help from another signed-in staff member. If every staff member is locked out, contact the clinic administrator.</p><button type="button" class="text-link recovery-back" id="recovery-back">Back to sign in</button>');
 const request=root.querySelector('#recovery-request-form'),reset=root.querySelector('#recovery-reset-form');
 for(const id of ['recovery-request-username','recovery-username'])root.querySelector('#'+id).value=username;
 function mode(useCode){const from=useCode?'recovery-request-username':'recovery-username',to=useCode?'recovery-username':'recovery-request-username';root.querySelector('#'+to).value=root.querySelector('#'+from).value;request.hidden=useCode;reset.hidden=!useCode;for(const [id,active]of [['choose-recovery-request',!useCode],['choose-recovery-code',useCode]]){const button=root.querySelector('#'+id);button.classList.toggle('primary',active);button.classList.toggle('secondary',!active);button.setAttribute('aria-pressed',String(active));}root.querySelector('[data-recovery-error]').hidden=true;updateFieldRequirements(root);}
 root.querySelector('#choose-recovery-request').onclick=()=>mode(false);root.querySelector('#choose-recovery-code').onclick=()=>mode(true);root.querySelector('#recovery-back').onclick=onBack;
 request.onsubmit=e=>{e.preventDefault();const input=Object.fromEntries(new FormData(request));void run(root,request,async()=>{const result=await api('password/request',{method:'POST',body:input});if(!request.isConnected)return;const out=root.querySelector('#recovery-request-success');setText(out,result.message);out.hidden=false;});};
 reset.onsubmit=e=>{e.preventDefault();const input=Object.fromEntries(new FormData(reset));void run(root,reset,async()=>{if(input.password!==input.confirmPassword)throw new Error('The new passwords do not match.');const result=await api('password/reset',{method:'POST',body:input});if(!reset.isConnected)return;reset.reset();onComplete(input.username,result.message);});};
 updateFieldRequirements(root);root.querySelector('#recovery-request-username').focus();
}
export function mountLockedCopy(root,{error,onBack,onSignIn}){
 root.innerHTML=markup('<h2>Your saved copy is still protected.</h2><p>The saved copy on this device needs your previous password. It may contain records that have not synced to the clinic.</p><form id="unlock-previous-copy"><label for="previous-copy-password">Previous password, if you remember it</label><input id="previous-copy-password" type="password" autocomplete="off" minlength="12" maxlength="128" required><button class="button primary" type="submit">Keep my saved changes</button></form><div class="recovery-copy-options"><p>If you cannot remember it, keep an encrypted backup before replacing this device’s copy with records saved at the clinic. The backup still needs your previous password to unlock it.</p><button type="button" class="button secondary" id="download-locked-copy">Download encrypted old copy</button><label class="check-field" for="replace-locked-copy"><input type="checkbox" id="replace-locked-copy" disabled>I saved the backup and want to use the clinic copy on this device.</label><button type="button" class="button primary" id="use-clinic-copy" disabled>Use clinic copy on this device</button></div><p class="notice warning" data-recovery-error role="alert" hidden></p><button type="button" class="text-link recovery-back" id="locked-copy-back">Back to sign in</button>');
 root.querySelector('#locked-copy-back').onclick=onBack;
 const form=root.querySelector('#unlock-previous-copy');form.onsubmit=e=>{e.preventDefault();const previousPassword=root.querySelector('#previous-copy-password').value;void run(root,form,()=>onSignIn({previousPassword}));};
 root.querySelector('#download-locked-copy').onclick=async()=>{try{const value=await AccountStore.encryptedCopyBackup(error.username,error.generation),url=URL.createObjectURL(new Blob([value],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='E-Nay-encrypted-old-copy-'+error.username+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);root.querySelector('#replace-locked-copy').disabled=false;updateFieldRequirements(root);}catch(error){failure(root,error);}};
 root.querySelector('#replace-locked-copy').onchange=e=>{root.querySelector('#use-clinic-copy').disabled=!e.target.checked;};
 root.querySelector('#use-clinic-copy').onclick=()=>{if(!root.querySelector('#replace-locked-copy').checked)return;void run(root,root,()=>onSignIn({replaceOfflineCopy:true,expectedGeneration:error.generation}));};updateFieldRequirements(root);
}
export function mountPasswordIssuer(root,store,account,onIssued){
 root.innerHTML=markup('<h3 id="recovery-target-name"></h3><p id="recovery-target-username"></p><p>Confirm the person’s identity using the clinic’s process before issuing a code. The person chooses their own new password.</p><form id="issue-recovery-form"><label class="check-field" for="recovery-identity-confirmed"><input id="recovery-identity-confirmed" type="checkbox" required>I verified this person’s identity.</label><label for="recovery-staff-password">Your current staff password</label><input id="recovery-staff-password" type="password" autocomplete="current-password" minlength="12" maxlength="128" required><button class="button primary" type="submit">Issue recovery code</button></form><p class="notice warning" data-recovery-error role="alert" hidden></p><div id="issued-recovery-code" hidden role="status"></div>');
 root.querySelector('#recovery-target-name').textContent=account.displayName;root.querySelector('#recovery-target-username').textContent='@'+account.username;
 const form=root.querySelector('#issue-recovery-form'),passwordField=root.querySelector('#recovery-staff-password');form.onsubmit=e=>{e.preventDefault();const input={accountId:account.id,identityConfirmed:root.querySelector('#recovery-identity-confirmed').checked,currentPassword:root.querySelector('#recovery-staff-password').value};void run(root,form,async()=>{try{const result=await api('admin/password-code',{method:'POST',proof:store.proof,body:input});if(!form.isConnected||form.closest('dialog')?.open===false)return;form.reset();form.hidden=true;const out=root.querySelector('#issued-recovery-code');out.hidden=false;out.innerHTML=markup('<p>Share this code privately with the verified account owner.</p><label for="issued-code-value">One-time recovery code</label><input id="issued-code-value" readonly><p>Expires in 15 minutes. Issuing another code cancels this one.</p><p>Ask them to choose Forgot password? on the sign-in page, then I have a recovery code.</p><button type="button" class="button secondary" id="copy-recovery-code">Copy recovery code</button>');out.querySelector('#issued-code-value').value=result.code;out.querySelector('#copy-recovery-code').onclick=async()=>{try{await navigator.clipboard.writeText(result.code);setText(out.querySelector('#copy-recovery-code'),'Copied');}catch{out.querySelector('#issued-code-value').select();}};onIssued?.();}finally{passwordField.value='';}});};updateFieldRequirements(root);
}
